#!/usr/bin/env bash
# Path: unplow/tools/unplow_viewer.sh
# Purpose: Real-time viewer & tracker for files generated by unplow.
# Uses jq to parse and format JSON audit journals, work products, and queues.
# Max Column: 80 (comments) / 120 (code)

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
JOURNAL="${REPO_ROOT}/logs/forensics/audit_journal.jsonl"
HEARTBEAT="${REPO_ROOT}/logs/heartbeat/unplow.json"
QUEUE_DIR="${REPO_ROOT}/records/queue"
WORK_PRODUCTS_DIR="${REPO_ROOT}/workspace/work_products"

# ANSI Color Codes
CYAN="\033[1;36m"
GREEN="\033[1;32m"
YELLOW="\033[1;33m"
BLUE="\033[1;34m"
MAGENTA="\033[1;35m"
BOLD="\033[1m"
RESET="\033[0m"

check_dependencies() {
    if ! command -v jq >/dev/null 2>&1; then
        echo -e "${YELLOW}[!] Warning: 'jq' not found. Installing jq will enable advanced formatting.${RESET}" >&2
    fi
}

show_header() {
    echo -e "${CYAN}========================================================================================${RESET}"
    echo -e "${BOLD}                     UNPLOW - DECOMPRESSION & ARTIFACT ACTIVITY VIEWER                  ${RESET}"
    echo -e "${CYAN}========================================================================================${RESET}"
}

show_queue_and_heartbeat() {
    echo -e "\n${BOLD}[System & Queue Status]${RESET}"
    if [ -f "${HEARTBEAT}" ]; then
        if command -v jq >/dev/null 2>&1; then
            jq -r '"  Daemon Status : \(.status) (PID \(.pid), RSS \(.rss_mb) MB, Host: \(.hostname // "localhost"))
  Model Substrate: \(.model_path)
  Processed     : \(.processed_tasks) tasks | Failed: \(.failed_tasks) tasks"' "${HEARTBEAT}"
        else
            cat "${HEARTBEAT}"
        fi
    else
        echo "  Heartbeat: No active daemon heartbeat found."
    fi

    local in_cnt proc_cnt done_cnt fail_cnt
    count_tasks() {
        local dir="$1"
        if [ -d "$dir" ]; then
            find "$dir" -name 'task-*.json' | wc -l
        else
            echo 0
        fi
    }
    in_cnt=$(count_tasks "${QUEUE_DIR}/incoming")
    proc_cnt=$(count_tasks "${QUEUE_DIR}/processing")
    done_cnt=$(count_tasks "${QUEUE_DIR}/done")
    fail_cnt=$(count_tasks "${QUEUE_DIR}/failed")

    echo -e "  Queue Counts  : ${YELLOW}Incoming: ${in_cnt}${RESET} | " \
            "${BLUE}Processing: ${proc_cnt}${RESET} | " \
            "${GREEN}Done: ${done_cnt}${RESET} | " \
            "${MAGENTA}Failed: ${fail_cnt}${RESET}"
}

show_recent_journal() {
    local limit="${1:-10}"
    echo -e "\n${BOLD}[Recent Forensic Audit Journal Events (last ${limit})]${RESET}"
    if [ ! -f "${JOURNAL}" ]; then
        echo "  No audit journal found at ${JOURNAL}."
        return
    fi

    if command -v jq >/dev/null 2>&1; then
        tail -n "${limit}" "${JOURNAL}" | jq -r '
            "  [\(.timestamp_utc // "unknown")] [\(.phase // "-")] \(.action // "-") " +
            "(task: \(.task_id // "-"), RSS: \(.telemetry.rss_mb // 0)MB)"
        '
    else
        tail -n "${limit}" "${JOURNAL}"
    fi
}

show_work_products() {
    echo -e "\n${BOLD}[Generated Decompression Work Products & Artifacts]${RESET}"
    if [ ! -d "${WORK_PRODUCTS_DIR}" ]; then
        echo "  No work products directory found."
        return
    fi

    local files
    files=$(find "${WORK_PRODUCTS_DIR}" -type f ! -name '.gitkeep' | sort -r)
    if [ -z "${files}" ]; then
        echo "  No work products generated yet."
        return
    fi

    echo "${files}" | while read -r f; do
        local sz
        sz=$(stat -c%s "$f" 2>/dev/null || echo 0)
        local rel="${f#"${REPO_ROOT}/"}"
        echo -e "  - ${GREEN}${rel}${RESET} (${sz} bytes)"
    done
}

case "${1:-summary}" in
    summary)
        show_header
        show_queue_and_heartbeat
        show_recent_journal 8
        show_work_products
        echo -e "\n${CYAN}========================================================================================${RESET}"
        ;;
    products)
        show_header
        show_work_products
        ;;
    follow)
        show_header
        echo -e "${YELLOW}[*] Streaming live forensic ledger (Ctrl+C to stop)...${RESET}\n"
        if [ -f "${JOURNAL}" ]; then
            tail -f "${JOURNAL}" | jq -r --unbuffered '
                "[\(.timestamp_utc)] [\(.phase)] task=\(.task_id) action=\(.action) details=\(.details)"
            '
        else
            echo "Waiting for ${JOURNAL} to be created..."
            while [ ! -f "${JOURNAL}" ]; do sleep 1; done
            tail -f "${JOURNAL}" | jq -r --unbuffered '
                "[\(.timestamp_utc)] [\(.phase)] task=\(.task_id) action=\(.action) details=\(.details)"
            '
        fi
        ;;
    *)
        echo "Usage: $0 {summary|products|follow}"
        exit 1
        ;;
esac

# end of file: unplow/tools/unplow_viewer.sh
